# AUTO-GENERATED by Claude Code
# Purpose: a player's results from start.gg: each recent set with opponent, score and seeds,
# and the win / loss tally. For Python use (scripts, notebooks, the kernel).
# NOT for the agent: ds.ai must never import this module (the user preps for opponents and
# doesn't want results brought up; tests/ds/ai/test_startgg_capability.py checks the import).
# Usage: `results = asyncio.run(player_results("Sparg0", months=3))`
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt

from pydantic import BaseModel, Field

from ds.data.raw import startgg
from ds.data.startgg.lookup import PlayerLookup, resolve_player
from ds.data.startgg.matchups import MatchupSet, matchup_sets

__all__ = ["PlayerResults", "SetResult", "player_results"]


class SetResult(MatchupSet):
    """One of the player's sets (they are player 1), with who the opponent was"""

    opponent: str = Field(description="Opponent's tag")
    opponent_id: int | None = Field(None, description="Opponent's start.gg player id")
    won: bool | None = None
    dq: bool = Field(default=False, description="The set ended by disqualification")


class PlayerResults(BaseModel):
    """A player's recent sets with results, newest first"""

    lookup: PlayerLookup
    sets: list[SetResult]
    sets_won: int
    sets_lost: int
    first_date: dt.date | None = None
    last_date: dt.date | None = None
    capped: bool = Field(description="True: `max_sets` was reached before `months`")


async def player_results(player: str, months: int = 6, max_sets: int = 150) -> PlayerResults:
    """A player's recent sets with opponent, scores and seeds, plus the tally

    Args:
        player: a tag, start.gg player id or profile url.
        months: how far back to look.
        max_sets: stop after this many sets.
    """
    lookup = await resolve_player(player)
    since = dt.datetime.now(dt.UTC) - dt.timedelta(days=30 * months)
    sets = await startgg.player_sets(lookup.player_id, max_sets=max_sets, since=since)
    kept = [s for s in sets if s.side_of(lookup.player_id) and s.opponent_of(lookup.player_id) and s.completed_at]
    rows = []
    for s, row in zip(kept, matchup_sets(kept, lookup.player_id), strict=True):
        rival = s.opponent_of(lookup.player_id)
        rows.append(
            SetResult(
                **row.model_dump(),
                opponent=rival.players[0].tag if rival.players else rival.name or "",
                opponent_id=rival.players[0].id if rival.players else None,
                won=None if row.winner is None else row.winner == 1,
                dq=-1 in {row.score_1, row.score_2} or (s.display_score or "").upper() == "DQ",
            )
        )
    return PlayerResults(
        lookup=lookup,
        sets=rows,
        sets_won=sum(1 for row in rows if row.won),
        sets_lost=sum(1 for row in rows if row.won is False),
        first_date=rows[-1].date if rows else None,
        last_date=rows[0].date if rows else None,
        capped=len(sets) >= max_sets,
    )
